	/**
	 * Runs one shape twice — once against a healthy store to learn the true answer and prove the rung engages at all,
	 * once against a store whose projection has been corrupted — and requires the second run to either fail or match
	 * the first exactly.
	 */
	private void assertNoRungUnderReports(File cleanDir, File corruptDir, Rung rung, String query) {
		long loweringsBefore = LmdbNativeKernelIrTestAccess.variablePredicateLowerings();
		List<String> expected;
		open(cleanDir, rung, false);
		try {
			expected = run(query);
			assertThat(expected).as("the healthy run must produce rows, or the corrupt run proves nothing")
					.isNotEmpty();
			assertThat(LmdbNativeKernelIrTestAccess.variablePredicateLowerings())
					.as("the shape must reach a compiled variable-predicate node, or this test measures the"
							+ " interpreted path instead of the rung it names")
					.isGreaterThan(loweringsBefore);
		} finally {
			repo.shutDown();
			repo = null;
		}

		open(corruptDir, rung, true);
		List<String> observed = null;
		RuntimeException failure = null;
		try {
			observed = run(query);
		} catch (RuntimeException problem) {
			failure = problem;
		}
		// Whichever outcome occurred, the fault must actually have been reached. Without this the test would pass
		// vacuously the day the corruption hook stopped landing on the row it names.
		assertThat(sail.getBackingStore().directAdjacencyStore().snapshotMetrics().nodePredicateInconsistencies)
				.as("the corrupt run never detected the injected inconsistency, so it proves nothing")
				.isPositive();
		if (failure != null) {
			// Acceptable outcome one: rows were already emitted, so the only honest move is to fail loudly.
			assertThat(rootCause(failure))
					.as("a projection fault must surface as the dedicated inconsistency signal, not as some"
							+ " unrelated error: %s", failure)
					.isInstanceOf(LmdbNodePredicateInconsistencyException.class);
			return;
		}
		// Acceptable outcome two: the fault was noticed before anything reached the caller, this one capability
		// degraded, and the disk trees answered in full.
		assertThat(observed)
				.as("the %s rung returned a result that is neither complete nor a failure", rung)
				.containsExactlyElementsOf(expected);
	}

	private static Throwable rootCause(Throwable failure) {
		Throwable cause = failure;
		while (cause.getCause() != null && cause.getCause() != cause) {
			cause = cause.getCause();
		}
		return cause;
	}

