	private List<String> run(String query) {
		List<String> rows = new ArrayList<>();
		try (RepositoryConnection connection = repo.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindings = result.next();
				StringBuilder row = new StringBuilder();
				for (String name : result.getBindingNames()) {
					row.append(name).append('=').append(bindings.getValue(name)).append('|');
				}
				rows.add(row.toString());
			}
		}
		rows.sort(String::compareTo);
		return rows;
	}

	private static String subjectBatch() {
		StringBuilder builder = new StringBuilder();
		for (int s = 0; s < SUBJECTS; s++) {
			builder.append('<').append(NS).append("s").append(s).append("> ");
		}
		return builder.toString().trim();
	}
